from __future__ import annotations

from datetime import datetime, timezone

import pytest

from gitseed.application import execute
from gitseed.collect.search import Candidate, CollectResult
from gitseed.evidence import ClaimBasis
from gitseed.grade.smoke import SmokeResult
from gitseed.grade.types import GradeResult
from gitseed.pipeline.run import FetchedFiles
from gitseed.ports import RepositoryMetadata, RunPorts, RunRequest
from gitseed.scoring import ScoreInputs


CANDIDATE = Candidate(
    repo="example/repository",
    owner="example",
    html_url="https://example.test/example/repository",
    stars=1,
    pushed_at="2026-01-01T00:00:00Z",
)


class _Repository:
    def __init__(self, calls: list[str]) -> None:
        self.calls = calls

    def search(self, query: str, limit: int) -> CollectResult:
        self.calls.append("search")
        return CollectResult(candidates=[CANDIDATE])

    def metadata(self, candidate: Candidate, at: datetime) -> RepositoryMetadata:
        self.calls.append("metadata")
        return RepositoryMetadata(ScoreInputs(True, True, True))


class _Files:
    def __init__(self, calls: list[str], fail: bool = False) -> None:
        self.calls = calls
        self.fail = fail

    def read(self, candidate: Candidate) -> FetchedFiles:
        self.calls.append("files")
        if self.fail:
            raise OSError("repository is unavailable")
        return FetchedFiles((("main.py", "print('ok')\n"),))


class _Model:
    def evaluate(self, digest: str) -> GradeResult:
        return GradeResult(7, 7, "fixture", "fixture", 0.0, "fixture-v1")

    def flags_malicious(self, digest: str) -> bool:
        return False


class _Clock:
    def __init__(self, calls: list[str]) -> None:
        self.calls = calls

    def now(self) -> datetime:
        self.calls.append("clock")
        return datetime(2026, 1, 1, tzinfo=timezone.utc)


class _CustomEvidenceReader:
    def __init__(self, names: frozenset[str], fail: bool = False) -> None:
        self.evidence_names = names
        self.fail = fail

    def read_evidence(self, candidate, files, metadata):
        if self.fail:
            raise RuntimeError("evidence source is unavailable")
        return ()


def _ports(calls: list[str], reader: _CustomEvidenceReader, *, file_failure: bool = False) -> RunPorts:
    return RunPorts(
        _Repository(calls),
        _Files(calls, file_failure),
        _Model(),
        _Clock(calls),
        reader,
    )


def test_custom_evidence_vocabulary_controls_validation_and_absence_records() -> None:
    # A selected pack must be rejected before execution when this reader cannot
    # supply one of the pack's requirements.
    calls: list[str] = []
    unsupported_reader = _CustomEvidenceReader(frozenset({"custom-language"}))
    with pytest.raises(ValueError) as error:
        execute(
            RunRequest("example", 1, ("mcp",)),
            _ports(calls, unsupported_reader),
            model_smoke=SmokeResult(True, "fixture"),
        )
    assert "mcp" in str(error.value)
    assert "manifest_entries" in str(error.value)
    assert calls == []

    # A compatible custom reader also has a non-default evidence name. Both a
    # file failure and a reader failure must expose precisely that vocabulary as
    # absent evidence in the returned artifact.
    for file_failure, reader_failure in ((True, False), (False, True)):
        calls = []
        reader = _CustomEvidenceReader(
            frozenset({"manifest_entries", "custom-language"}),
            fail=reader_failure,
        )
        artifact = execute(
            RunRequest("example", 1, ("mcp",)),
            _ports(calls, reader, file_failure=file_failure),
            model_smoke=SmokeResult(True, "fixture"),
        )

        trace = artifact.repositories[0]
        assert frozenset(item.evidence for item in trace.category_evidence) == reader.evidence_names
        assert all(item.values == frozenset() for item in trace.category_evidence)
        assert all(item.basis is ClaimBasis.ABSENT for item in trace.category_evidence)
        assert trace.categories[0].category is None
        assert trace.categories[0].basis is ClaimBasis.ABSENT
        assert trace.categories[0].missing_evidence == ("manifest_entries",)
